package com.mewcode.tool;
import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.StandardOpenOption;import java.util.LinkedHashMap;import java.util.Map;import java.util.Optional;
public final class JsonlToolExecutionLedger {private static final ObjectMapper JSON=new ObjectMapper().registerModule(new JavaTimeModule());private final Path path;private final Map<String,ToolExecutionRecord> latest=new LinkedHashMap<>();
 public JsonlToolExecutionLedger(Path workspace,String sessionId,String runId){this.path=workspace.resolve(".mewcode/sessions").resolve(sessionId==null?"default":sessionId).resolve("tool-ledger.jsonl");load();for(var r:java.util.List.copyOf(latest.values()))if(r.status()==ToolExecutionRecord.Status.PENDING&&!runId.equals(r.runId()))append(new ToolExecutionRecord(r.toolCallId(),r.toolName(),r.effect(),ToolExecutionRecord.Status.UNKNOWN,r.argsHash(),r.beforeHash(),r.afterHash(),r.diffHash(),r.result(),r.runId(),java.time.Instant.now()));}
 public synchronized Optional<ToolExecutionRecord> find(String id){return Optional.ofNullable(latest.get(id));}
 public synchronized void append(ToolExecutionRecord r){try{Files.createDirectories(path.getParent());Files.writeString(path,JSON.writeValueAsString(r)+System.lineSeparator(),StandardOpenOption.CREATE,StandardOpenOption.APPEND);latest.put(r.toolCallId(),r);}catch(Exception e){throw new IllegalStateException("Cannot append tool ledger",e);}}
 private void load(){if(!Files.exists(path))return;try{for(String line:Files.readAllLines(path)){try{var r=JSON.readValue(line,ToolExecutionRecord.class);latest.put(r.toolCallId(),r);}catch(Exception ignored){break;}}}catch(Exception ignored){}}
}
